class TranslateMixin:
    """TranslateMixin — 7 个方法"""

    TRANSLATE_PROMPT = """你是一名专业翻译。请将以下 {source_lang} 文本准确翻译成 {target_lang}，保持每条文本的编号顺序：

{numbered}

请直接输出 JSON 字符串数组（每条文本对应一个元素），不要加 markdown 代码块标记，不要输出任何解释。格式示例：
["译文1", "译文2", "..."]"""

    @staticmethod
    def _lang_name(lang_code: str) -> str:
        """语言代码 → 中文名称（用于 Gemini prompt）"""
        m = {
            "zh": "简体中文", "zh-CN": "简体中文", "zh-TW": "繁体中文",
            "en": "英语", "de": "德语", "fr": "法语", "es": "西班牙语",
            "ja": "日语", "ko": "韩语", "ru": "俄语", "it": "意大利语",
            "pt": "葡萄牙语", "ar": "阿拉伯语", "auto": "自动检测",
        }
        return m.get(lang_code, lang_code)


    @staticmethod
    def _parse_json_array(text: str) -> Optional[List[str]]:
        """从 Gemini 返回文本中尽力解析 JSON 字符串数组，失败返回 None"""
        if not text:
            return None
        try:
            content = text.strip()
            if content.startswith("```"):
                lines = content.split("\n")
                if lines and lines[0].startswith("```"):
                    lines = lines[1:]
                if lines and lines[-1].strip() == "```":
                    lines = lines[:-1]
                content = "\n".join(lines)
            arr = json.loads(content)
            if isinstance(arr, list):
                return [str(x).strip() for x in arr]
        except Exception:
            pass
        # 兜底：尝试从整段文本中提取 [...] 数组段
        m = re.search(r"\[.*\]", text, re.DOTALL)
        if m:
            try:
                arr = json.loads(m.group(0))
                if isinstance(arr, list):
                    return [str(x).strip() for x in arr]
            except Exception:
                pass
        return None


    def translate_texts(
        self,
        texts: List[str],
        source_lang: str = "auto",
        target_lang: str = "zh-CN",
    ) -> List[str]:
        """用 Gemini 直接翻译一批文本（无任何其它引擎兜底）

        Args:
            texts: 原文列表
            source_lang: 源语言代码
            target_lang: 目标语言代码

        Returns:
            译文列表（长度与 texts 一致）。Gemini 不可用或整批失败时每项返回原文，
            并在日志 ERROR 提示检查配置。
        """
        texts = [t for t in texts]  # 拷贝
        if not texts:
            return []
        if not self.is_available:
            logger.error("[Gemini 翻译] 未启用或 api_key 未配置，无法翻译，返回原文")
            return list(texts)

        return self._translate_batch(texts, source_lang, target_lang)


    def _translate_batch(
        self,
        texts: List[str],
        source_lang: str,
        target_lang: str,
    ) -> List[str]:
        """按批调用 Gemini 翻译并拆回；单批失败时该批返回原文。

        处理要点：
          - 短文本走批量合并（字幕等数百行场景高效）。
          - 超过 SHORT_LIMIT 的长文本（如较长的视频简介）按行分块、每块单独
            generate_content（单元素），再按序拼接。否则长文本里的大量换行会
            使 Gemini 误拆成多个数组元素，导致截取后译文只剩第一小段。
        """
        from core.translation_engine import merge_texts, split_translated

        SHORT_LIMIT = 900  # 单条超过此字符数即独立翻译

        src_name = self._lang_name(source_lang)
        tgt_name = self._lang_name(target_lang)

        results: List[str] = list(str(t) for t in texts)  # 默认原文兜底
        pending_idx: List[int] = []   # 待批量翻译的短文本在原列表中的下标
        pending_texts: List[str] = []

        def _flush_short() -> None:
            """把已积攒的短文本合并成一批翻译"""
            if not pending_texts:
                return
            batches = merge_texts(pending_texts, 3500)
            out: List[str] = []
            for batch in batches:
                part_count = batch.count("|||SPLIT|||") + 1 if batch else 0
                translated = self._translate_one_prompt(batch, part_count, src_name, tgt_name)
                if translated is None:
                    out.extend(batch.split("|||SPLIT|||") if batch else [])
                    continue
                if part_count <= 1:
                    out.append(translated)
                else:
                    out.extend(split_translated(translated, part_count))
            for j, idx in enumerate(pending_idx):
                if j < len(out) and out[j]:
                    results[idx] = out[j]
            pending_idx.clear()
            pending_texts.clear()

        for i, t in enumerate(texts):
            t = str(t)
            if len(t) <= SHORT_LIMIT:
                pending_idx.append(i)
                pending_texts.append(t)
            else:
                # 先把已积攒的短文本批量翻译掉，保持输出顺序一致
                _flush_short()
                chunks = self._chunk_by_lines(t, SHORT_LIMIT)
                segs = []
                for c in chunks:
                    tr = self._translate_one_prompt(c, 1, src_name, tgt_name)
                    segs.append(tr if tr else c)
                results[i] = "\n".join(x for x in segs if x)
        _flush_short()
        return results


    @staticmethod
    def _chunk_by_lines(text: str, limit: int) -> List[str]:
        """把长文本按换行切分，使每块不超过 limit 字符（保留段落边界）"""
        lines = text.split("\n")
        chunks: List[str] = []
        cur = ""
        for ln in lines:
            candidate = (cur + "\n" + ln).strip() if cur else ln
            # 单行超限则强制按字符截断
            while len(candidate) > limit:
                if cur:
                    chunks.append(cur)
                    cur = ""
                chunks.append(ln[:limit])
                ln = ln[limit:]
                candidate = ln if cur == "" else ln
            cur = candidate
        if cur:
            chunks.append(cur)
        return chunks


    def _translate_one_prompt(
        self,
        batch_text: str,
        expected_count: int,
        src_name: str,
        tgt_name: str,
    ) -> Optional[str]:
        """对单个批次调用一次 Gemini generate_content，返回含 SPLIT 的译文；失败返回 None"""
        parts = batch_text.split("|||SPLIT|||") if "|||SPLIT|||" in batch_text else [batch_text]
        numbered = "\n".join(f"{i + 1}. {p}" for i, p in enumerate(parts))
        prompt = self.TRANSLATE_PROMPT.format(
            source_lang=src_name, target_lang=tgt_name, numbered=numbered
        )

        client = self._get_client()
        model_chain = list(self._model_chain)
        response = None
        last_exc: Optional[Exception] = None

        for model in model_chain:
            if _is_model_exhausted(model):
                continue
            for attempt in range(1, self.RETRIES_PER_MODEL + 1):
                try:
                    self._log_prompt(f"翻译[{model}]", prompt)
                    with GEMINI_RATE_LIMITER:
                        response = client.models.generate_content(
                            model=model,
                            contents=prompt,
                        )
                    last_exc = None
                    break
                except Exception as e:
                    last_exc = e
                    if _is_429(e):
                        is_quota = _is_quota_exhausted(e)
                        delay = _extract_retry_delay(e) or 10.0
                        if is_quota:
                            exh_model = _extract_exhausted_model(e)
                            if exh_model:
                                _mark_model_exhausted(exh_model)
                            else:
                                _mark_model_exhausted(model)
                            logger.warning(
                                f"[Gemini 翻译] [{model}] ❗ 今日配额耗尽 → 降级"
                            )
                        else:
                            logger.warning(
                                f"[Gemini 翻译] [{model}] ⚠ RPM 限流 → 等待 {delay:.1f}s 后降级"
                            )
                            time.sleep(delay)
                        break   # 不再内部重试当前模型
                    if is_retryable_error(e) and attempt < self.RETRIES_PER_MODEL:
                        backoff = _backoff_seconds(attempt)
                        if self._is_connection_error(e):
                            logger.warning(
                                f"[Gemini 翻译] [{model}] 🔌 连接类错误 → "
                                f"重建 httpx 连接池后 retry {attempt + 1}/{self.RETRIES_PER_MODEL}"
                            )
                            client = self._reset_client()
                        else:
                            logger.warning(
                                f"[Gemini 翻译] [{model}] API 失败 "
                                f"(retry {attempt}/{self.RETRIES_PER_MODEL}): {str(e)[:120]} "
                                f"— {backoff:.1f}s 后重试"
                            )
                        time.sleep(backoff)
                        continue
                    break
            if response is not None:
                break

        if response is None:
            logger.warning(f"[Gemini 翻译] 全部模型失败: {last_exc}")
            return None

        # 提取文本
        raw_text = ""
        try:
            raw_text = response.text or ""
        except Exception:
            pass
        if not raw_text:
            try:
                for part in getattr(response, "parts", []) or []:
                    raw_text += getattr(part, "text", "") or ""
            except Exception:
                pass
        if not raw_text.strip():
            raw_text = str(response)

        arr = self._parse_json_array(raw_text)
        if arr is None:
            logger.warning(
                f"[Gemini 翻译] 返回非 JSON 数组，无法拆分，回退原文: {raw_text[:160]}"
            )
            return None

        # 对齐数量
        if len(parts) == 1 and len(arr) > 1:
            # 单条输入但模型自作主张拆成多句（典型：长简介被拆成 5~6 段）——
            # 把它们全拼回来，避免 arr[:1] 截断导致译文中间段遗失。
            logger.warning(
                f"[Gemini 翻译] expected_count=1 但模型返回 {len(arr)} 条，自动拼接"
            )
            translated_parts = [" ".join(p for p in arr if p)]
        else:
            translated_parts = arr[:len(parts)]
        while len(translated_parts) < len(parts):
            translated_parts.append("")
        return "|||SPLIT|||".join(translated_parts)


    @staticmethod
    def _serialize_items_for_prompt(items: List[Dict[str, Any]], max_lines: int = 600) -> str:
        """把字幕 dict 列表序列化成紧凑文本，塞进校对 prompt"""
        lines: List[str] = []
        for i, it in enumerate(items[:max_lines], 1):
            st = it.get("start_time", 0)
            et = it.get("end_time", 0)
            src = str(it.get("source_text", "")).replace("\n", " ").strip()
            tgt = str(it.get("target_text", "")).replace("\n", " ").strip()
            lines.append(f"{i}. [{st:.1f}s-{et:.1f}s] {src} || {tgt}")
        if len(items) > max_lines:
            lines.append(f"... (共 {len(items)} 条，此处只列前 {max_lines} 条)")
        return "\n".join(lines)

